<script setup lang="ts">import {computed} from 'vue';import {categoryPaths} from '../../../../../packages/common/utils/commercePresentation';const props=defineProps<{rows:Array<{id:string;name:string;parentId?:string|null}>;selected?:string}>();const emit=defineEmits<{select:[id:string]}>();const options=computed(()=>[{id:'',path:'全部商品'},...categoryPaths(props.rows)]);</script>
<template><picker :range="options" range-key="path" :value="Math.max(0,options.findIndex(r=>r.id===selected))" @change="emit('select',options[Number($event.detail.value)].id)"><view class="s2-category"><text>商品分类</text><text>{{options.find(r=>r.id===selected)?.path||'全部商品'}} ›</text></view></picker></template>
<style scoped lang="scss">.s2-category{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:48px;padding:12px;background:$color-card-bg;border:1px solid $color-border;border-radius:$radius-card;font-size:15px;line-height:24px}.s2-category text:last-child{flex:1;min-width:0;text-align:right;overflow-wrap:anywhere;color:$color-primary}</style>
